CREATE TABLE "AICourse" ("id" TEXT PRIMARY KEY,"actorId" TEXT NOT NULL,"title" TEXT NOT NULL,"kind" TEXT NOT NULL DEFAULT 'course',"prompt" TEXT NOT NULL,"settings" JSONB NOT NULL,"revision" INTEGER NOT NULL DEFAULT 1,"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "AICourse_archivedAt_updatedAt_idx" ON "AICourse"("archivedAt","updatedAt");
CREATE TABLE "AICourseModule" ("id" TEXT PRIMARY KEY,"courseId" TEXT NOT NULL REFERENCES "AICourse"("id"),"title" TEXT NOT NULL,"brief" TEXT NOT NULL DEFAULT '',"minutes" INTEGER NOT NULL DEFAULT 10,"style" TEXT NOT NULL DEFAULT 'slides',"position" INTEGER NOT NULL,"revision" INTEGER NOT NULL DEFAULT 1,"lesson" JSONB NOT NULL DEFAULT '{}',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "AICourseModule_courseId_position_idx" ON "AICourseModule"("courseId","position");
CREATE TABLE "AICourseMaterial" ("id" TEXT PRIMARY KEY,"moduleId" TEXT NOT NULL REFERENCES "AICourseModule"("id"),"title" TEXT NOT NULL,"kind" TEXT NOT NULL,"instructions" TEXT NOT NULL DEFAULT '',"content" JSONB NOT NULL DEFAULT '{}',"revision" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AICourseMaterial_moduleId_idx" ON "AICourseMaterial"("moduleId");
CREATE TABLE "AICourseTask" ("id" TEXT PRIMARY KEY,"courseId" TEXT NOT NULL REFERENCES "AICourse"("id"),"actorId" TEXT NOT NULL,"requestId" TEXT NOT NULL UNIQUE,"kind" TEXT NOT NULL,"input" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"error" TEXT,"usage" JSONB NOT NULL DEFAULT '{}',"leaseToken" TEXT,"startedAt" TIMESTAMP(3),"heartbeatAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "AICourseTask_courseId_status_idx" ON "AICourseTask"("courseId","status");
CREATE INDEX "AICourseTask_status_heartbeatAt_idx" ON "AICourseTask"("status","heartbeatAt");
CREATE TABLE "AICourseAsset" ("id" TEXT PRIMARY KEY,"moduleId" TEXT NOT NULL REFERENCES "AICourseModule"("id"),"revision" INTEGER NOT NULL,"scene" INTEGER NOT NULL,"kind" TEXT NOT NULL,"path" TEXT NOT NULL,"mime" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "AICourseAsset_moduleId_revision_scene_kind_key" ON "AICourseAsset"("moduleId","revision","scene","kind");
CREATE TABLE "AICourseCredential" ("provider" TEXT PRIMARY KEY,"encryptedKey" TEXT NOT NULL,"maskedKey" TEXT NOT NULL,"revision" INTEGER NOT NULL DEFAULT 1,"models" JSONB NOT NULL DEFAULT '[]',"voices" JSONB NOT NULL DEFAULT '[]',"verifiedAt" TIMESTAMP(3),"updatedAt" TIMESTAMP(3) NOT NULL);
